v as (
    select table_name, column_name, data_type, character_maximum_length, numeric_precision, numeric_scale
      from BAGIC_PREPROD_CURATED_DB.INFORMATION_SCHEMA.COLUMNS where table_schema = 'BGIL_DATA_MODEL'
),
r as (
    select table_name, column_name, data_type, character_maximum_length, numeric_precision, numeric_scale
      from BAGIC_PROD_MIRROR_DB.INFORMATION_SCHEMA.COLUMNS where table_schema = 'OPUS_GG_DWHSTAGE'
),
x as (
    select 'OPUS' as project, m.*,
           r.data_type as raw_type, r.character_maximum_length as raw_length, r.numeric_precision as raw_precision, r.numeric_scale as raw_scale,
           v.data_type as sat_type, v.character_maximum_length as sat_length, v.numeric_precision as sat_precision, v.numeric_scale as sat_scale,
           case when r.data_type is null then 'RAW_COLUMN_NOT_FOUND'
                when v.data_type is null then 'SAT_COLUMN_NOT_FOUND'
                when v.data_type = 'TEXT' and r.data_type = 'TEXT' and v.character_maximum_length < r.character_maximum_length then 'LENGTH_TRUNCATION_RISK'
                when v.data_type = 'NUMBER' and r.data_type = 'NUMBER'
                     and (v.numeric_scale < r.numeric_scale or v.numeric_precision - v.numeric_scale < r.numeric_precision - r.numeric_scale) then 'NUMERIC_PRECISION_LOSS'
                when v.data_type = r.data_type then 'SAME_TYPE'
                when v.data_type = 'TEXT' then 'STORED_AS_TEXT'
                when m.model_converts then 'CONVERTED_BY_MODEL'
                else 'TYPE_CHANGED' end as classification,
           case when classification in ('SAME_TYPE', 'CONVERTED_BY_MODEL') then 'PASS'
                when classification = 'STORED_AS_TEXT' then 'PASS (value format verified in DM-A1 (b))'
                else 'FAIL' end as status
      from m
      left join r on r.table_name = m.raw_table and r.column_name = m.raw_column
      left join v on v.table_name = m.satellite and v.column_name = m.sat_column
)
select * from x
 order by iff(status = 'FAIL', 0, 1), satellite, sat_column, raw_table;



----------------------------------------------------------------------------------------
-- 2. OPUS — SAT_COMMON_ADDRESS   [Implemented]
-- standard satellite, sat_multi_source; PK LOCATION_HKEY; 2 RECORD_SOURCE group(s):
-- OPUS_BJAZ_TRV_LOADER_DATA [5 col(s)], OPUS_BJAZ_TRV_LOADER_LOG_TABLE [6 col(s)].
-- stg2_common_address_bjaz_trv_loader_data: column(s) COUNTRY_NAME could not be traced
-- to RAW on at least one arm -- excluded (first-cut: walk columns from resolved_mt__
-- views or joined-in stitch columns are not yet inlined into the sampled queries).
-- TRIMMED / BLANK_TO_NULL on trim / nullif columns = documented exception (staging trim
-- rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct LOCATION_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADDRESS
     where RECORD_SOURCE = 'OPUS_BJAZ_TRV_LOADER_DATA'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select LOCATION_HKEY as hkey,
           to_varchar(BUILDING_NAME) as BUILDING_NAME,
           to_varchar(CITY) as CITY,
           to_varchar(POSTAL_CODE) as POSTAL_CODE,
           to_varchar(STATE_NAME) as STATE_NAME,
           to_varchar(STREET_NAME) as STREET_NAME
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADDRESS
     where RECORD_SOURCE = 'OPUS_BJAZ_TRV_LOADER_DATA'
       and LOCATION_HKEY in (select hkey from s1)
    qualify rank() over (partition by LOCATION_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_travel__bjaz_trv_loader_data
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (coalesce((nullif(trim(to_varchar("BUILDING")), '')), '') || '|' || coalesce((nullif(trim(to_varchar("STREETNAME")), '')), '') || '|' || coalesce((nullif(trim(to_varchar("SUBAREACITY")), '')), '') || '|' || coalesce((nullif(trim(to_varchar("STATE")), '')), '') || '|' || coalesce((nullif(trim(to_varchar("PINCODE")), '')), '')) AS VARCHAR))), '')) as hkey,
               ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
               to_varchar("BUILDING") as BUILDING_NAME,
               to_varchar("SUBAREACITY") as CITY,
               to_varchar("PINCODE") as POSTAL_CODE,
               to_varchar("STATE") as STATE_NAME,
               to_varchar("STREETNAME") as STREET_NAME
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_TRV_LOADER_DATA
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'BUILDING_NAME' as column_name, 'BUILDING' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.BUILDING_NAME, e.BUILDING_NAME) then 0
                when c.BUILDING_NAME is null and nullif(trim(e.BUILDING_NAME), '') is null then 1
                when c.BUILDING_NAME = trim(e.BUILDING_NAME) then 2
                when upper(c.BUILDING_NAME) = upper(trim(e.BUILDING_NAME)) then 3
                when try_to_decimal(c.BUILDING_NAME, 38, 10) = try_to_decimal(trim(e.BUILDING_NAME), 38, 10) then 4
                when try_to_timestamp_ntz(c.BUILDING_NAME) = try_to_timestamp_ntz(trim(e.BUILDING_NAME)) then 5
                when length(c.BUILDING_NAME) < length(e.BUILDING_NAME) and startswith(e.BUILDING_NAME, c.BUILDING_NAME) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.BUILDING_NAME
    union all
    select 'CITY' as column_name, 'SUBAREACITY' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.CITY, e.CITY) then 0
                when c.CITY is null and nullif(trim(e.CITY), '') is null then 1
                when c.CITY = trim(e.CITY) then 2
                when upper(c.CITY) = upper(trim(e.CITY)) then 3
                when try_to_decimal(c.CITY, 38, 10) = try_to_decimal(trim(e.CITY), 38, 10) then 4
                when try_to_timestamp_ntz(c.CITY) = try_to_timestamp_ntz(trim(e.CITY)) then 5
                when length(c.CITY) < length(e.CITY) and startswith(e.CITY, c.CITY) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.CITY
    union all
    select 'POSTAL_CODE' as column_name, 'PINCODE' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.POSTAL_CODE, e.POSTAL_CODE) then 0
                when c.POSTAL_CODE is null and nullif(trim(e.POSTAL_CODE), '') is null then 1
                when c.POSTAL_CODE = trim(e.POSTAL_CODE) then 2
                when upper(c.POSTAL_CODE) = upper(trim(e.POSTAL_CODE)) then 3
                when try_to_decimal(c.POSTAL_CODE, 38, 10) = try_to_decimal(trim(e.POSTAL_CODE), 38, 10) then 4
                when try_to_timestamp_ntz(c.POSTAL_CODE) = try_to_timestamp_ntz(trim(e.POSTAL_CODE)) then 5
