      from (
        -- via stg_travel__bjaz_trv_plan
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_COVERAGE|' || ((nullif(trim(to_varchar("COVER_CODE")), ''))) AS VARCHAR))), '')) as hkey,
               ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
               to_varchar("CLAIM_COVER_DESC") as CONDITION_DESCRIPTION,
               to_varchar("DEDUCTABLE_TIME") as WAITING_PERIOD_CONDITION
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_TRV_PLAN
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'CONDITION_DESCRIPTION' as column_name, 'CLAIM_COVER_DESC' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.CONDITION_DESCRIPTION, e.CONDITION_DESCRIPTION) then 0
                when c.CONDITION_DESCRIPTION is null and nullif(trim(e.CONDITION_DESCRIPTION), '') is null then 1
                when c.CONDITION_DESCRIPTION = trim(e.CONDITION_DESCRIPTION) then 2
                when upper(c.CONDITION_DESCRIPTION) = upper(trim(e.CONDITION_DESCRIPTION)) then 3
                when try_to_decimal(c.CONDITION_DESCRIPTION, 38, 10) = try_to_decimal(trim(e.CONDITION_DESCRIPTION), 38, 10) then 4
                when try_to_timestamp_ntz(c.CONDITION_DESCRIPTION) = try_to_timestamp_ntz(trim(e.CONDITION_DESCRIPTION)) then 5
                when length(c.CONDITION_DESCRIPTION) < length(e.CONDITION_DESCRIPTION) and startswith(e.CONDITION_DESCRIPTION, c.CONDITION_DESCRIPTION) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.CONDITION_DESCRIPTION
    union all
    select 'WAITING_PERIOD_CONDITION' as column_name, 'DEDUCTABLE_TIME' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.WAITING_PERIOD_CONDITION, e.WAITING_PERIOD_CONDITION) then 0
                when c.WAITING_PERIOD_CONDITION is null and nullif(trim(e.WAITING_PERIOD_CONDITION), '') is null then 1
                when c.WAITING_PERIOD_CONDITION = trim(e.WAITING_PERIOD_CONDITION) then 2
                when upper(c.WAITING_PERIOD_CONDITION) = upper(trim(e.WAITING_PERIOD_CONDITION)) then 3
                when try_to_decimal(c.WAITING_PERIOD_CONDITION, 38, 10) = try_to_decimal(trim(e.WAITING_PERIOD_CONDITION), 38, 10) then 4
                when try_to_timestamp_ntz(c.WAITING_PERIOD_CONDITION) = try_to_timestamp_ntz(trim(e.WAITING_PERIOD_CONDITION)) then 5
                when length(c.WAITING_PERIOD_CONDITION) < length(e.WAITING_PERIOD_CONDITION) and startswith(e.WAITING_PERIOD_CONDITION, c.WAITING_PERIOD_CONDITION) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.WAITING_PERIOD_CONDITION
)
select 'OPUS' as project, 'SAT_COVERAGE_CONDITIONS' as satellite, 'OPUS_BJAZ_TRV_PLAN' as record_source,
       column_name, raw_column, model_rule, count(*) as keys_compared,
       count_if(src_rows > 0 and cls = 0) as exact,
       count_if(src_rows > 0 and cls = 1) as blank_to_null,
       count_if(src_rows > 0 and cls = 2) as trimmed,
       count_if(src_rows > 0 and cls = 3) as case_changed,
       count_if(src_rows > 0 and cls = 4) as number_format_changed,
       count_if(src_rows > 0 and cls = 5) as date_format_changed,
       count_if(src_rows > 0 and cls = 6) as truncated,
       count_if(src_rows > 0 and cls = 7) as value_differs,
       count_if(src_rows = 0) as no_source_row,
       iff(truncated = 0
           and (value_differs = 0 or any_value(r_conv))
           and (trimmed = 0 or any_value(r_trim))
           and (blank_to_null = 0 or any_value(r_nullif))
           and (case_changed = 0 or any_value(r_case))
           and (number_format_changed + date_format_changed = 0 or any_value(r_conv)), 'PASS', 'FAIL') as status
  from r1
 group by column_name, raw_column, model_rule
order by record_source, column_name;



