-- 32. OPUS — SAT_RISK_OBJECT_CORE   [Implemented]
-- standard satellite, automate_dv.sat; PK RISK_OBJECT_HKEY; 1 RECORD_SOURCE group(s):
-- OPUS_BJAZ_TRV_LOADER_LOG_TABLE [1 col(s)]. TRIMMED / BLANK_TO_NULL on trim / nullif
-- columns = documented exception (staging trim rule retained by design), not a failure.
----------------------------------------------------------------------------------------
with s1 as (  -- deterministic sample: first 100 keys of this RECORD_SOURCE by hash key
    select distinct RISK_OBJECT_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_RISK_OBJECT_CORE
     where RECORD_SOURCE = 'OPUS_BJAZ_TRV_LOADER_LOG_TABLE'
     order by hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select RISK_OBJECT_HKEY as hkey,
           to_varchar(EXPOSURE_QUANTITY) as EXPOSURE_QUANTITY
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_RISK_OBJECT_CORE
     where RECORD_SOURCE = 'OPUS_BJAZ_TRV_LOADER_LOG_TABLE'
       and RISK_OBJECT_HKEY in (select hkey from s1)
    qualify rank() over (partition by RISK_OBJECT_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_travel__bjaz_trv_loader_log_table
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_RISK_OBJECT|' || ((nullif(trim(to_varchar("POLICYNUMBER")), ''))) AS VARCHAR))), '')) as hkey,
               ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
               to_varchar("DISTANCE") as EXPOSURE_QUANTITY
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_TRV_LOADER_LOG_TABLE
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'EXPOSURE_QUANTITY' as column_name, 'DISTANCE' as raw_column, 'trim+nullif' as model_rule,
           true as r_trim, true as r_nullif, false as r_case, false as r_conv,
           c.hkey, count(e.hkey) as src_rows,
           min(case when equal_null(c.EXPOSURE_QUANTITY, e.EXPOSURE_QUANTITY) then 0
                when c.EXPOSURE_QUANTITY is null and nullif(trim(e.EXPOSURE_QUANTITY), '') is null then 1
                when c.EXPOSURE_QUANTITY = trim(e.EXPOSURE_QUANTITY) then 2
                when upper(c.EXPOSURE_QUANTITY) = upper(trim(e.EXPOSURE_QUANTITY)) then 3
                when try_to_decimal(c.EXPOSURE_QUANTITY, 38, 10) = try_to_decimal(trim(e.EXPOSURE_QUANTITY), 38, 10) then 4
                when try_to_timestamp_ntz(c.EXPOSURE_QUANTITY) = try_to_timestamp_ntz(trim(e.EXPOSURE_QUANTITY)) then 5
                when length(c.EXPOSURE_QUANTITY) < length(e.EXPOSURE_QUANTITY) and startswith(e.EXPOSURE_QUANTITY, c.EXPOSURE_QUANTITY) then 6
                else 7 end) as cls
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.EXPOSURE_QUANTITY
)
select 'OPUS' as project, 'SAT_RISK_OBJECT_CORE' as satellite, 'OPUS_BJAZ_TRV_LOADER_LOG_TABLE' as record_source,
       column_name, raw_column, model_rule, count(*) as keys_compared,
       count_if(src_rows > 0 and cls = 0) as exact,
       count_if(src_rows > 0 and cls = 1) as blank_to_null,
       count_if(src_rows > 0 and cls = 2) as trimmed,
       count_if(src_rows > 0 and cls = 3) as case_changed,
       count_if(src_rows > 0 and cls = 4) as number_format_changed,
       count_if(src_rows > 0 and cls = 5) as date_format_changed,
       count_if(src_rows > 0 and cls = 6) as truncated,
       count_if(src_rows > 0 and cls = 7) as value_differs,
       count_if(src_rows = 0) as no_source_row,
       iff(truncated = 0
           and (value_differs = 0 or any_value(r_conv))
           and (trimmed = 0 or any_value(r_trim))
           and (blank_to_null = 0 or any_value(r_nullif))
